// Guard suite for the A1.2 Wortliste migration (Course Factory Wave 3, PR B).
//
// migrations/2026-09-05-a1-2-wortliste.sql is generated by
// scripts/words-from-json.mjs from the reviewed addition/fix JSON — the
// same generic script that wrote migrations/2026-09-05-a1-1-wortliste.sql,
// now generalised to derive the level from its input rather than hardcode
// "a1.1". This test parses the GENERATED SQL (not the source JSON) so a
// hand-edit that breaks the re-run contract — an INSERT missing its WHERE
// NOT EXISTS guard, an UPDATE missing its IS NOT DISTINCT FROM guard, a
// plural regression back to the literal string "null" — fails here even if
// the JSON inputs stay clean. It also pins VOCAB_WORD_COUNT against the new
// total (see tests/a1-1-wortliste.test.mjs for the article/plural display
// bug guard, which is level-agnostic and not repeated here).

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { VOCAB_WORD_COUNT } from '../src/data/marketing.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const MIGRATION = 'migrations/2026-09-05-a1-2-wortliste.sql';

const sql = readFileSync(join(ROOT, MIGRATION), 'utf8');

// ---------------------------------------------------------------------------
// Parse the generated SQL back into statement blocks (see
// tests/a1-1-wortliste.test.mjs for why this is safe against the actual
// generated file: string literals in the data can contain commas but never
// a bare ";").
// ---------------------------------------------------------------------------

const insertBlocks = [...sql.matchAll(/INSERT INTO public\.words[\s\S]*?\n\);/g)].map((m) => m[0]);
const updateBlocks = [...sql.matchAll(/UPDATE public\.words SET[\s\S]*?;/g)].map((m) => m[0]);

test('the migration has exactly 166 INSERT statements', () => {
  assert.equal(insertBlocks.length, 166);
});

test('every INSERT targets level a1.2', () => {
  for (const block of insertBlocks) {
    assert.match(block, /SELECT 'a1\.2',/, `INSERT missing/wrong level literal:\n${block}`);
    assert.match(block, /AND level = 'a1\.2'/, `INSERT's guard missing level = 'a1.2':\n${block}`);
  }
});

test('no INSERT carries the literal string "null" as a value', () => {
  for (const block of insertBlocks) {
    assert.ok(!block.includes("'null'"), `INSERT carries the literal string 'null':\n${block}`);
  }
});

test('every INSERT is guarded by WHERE NOT EXISTS on (german, level, category)', () => {
  for (const block of insertBlocks) {
    assert.match(
      block,
      /WHERE NOT EXISTS \(\s*SELECT 1 FROM public\.words WHERE german = '.*?' AND level = 'a1\.2' AND category = '.*?'\s*\)/,
      `INSERT missing a proper WHERE NOT EXISTS guard:\n${block}`,
    );
  }
});

test('the migration has exactly 54 UPDATE statements', () => {
  assert.equal(updateBlocks.length, 54);
});

test('every UPDATE is guarded by an IS NOT DISTINCT FROM on the old value', () => {
  for (const block of updateBlocks) {
    assert.match(
      block,
      /WHERE id = '[0-9a-f-]{36}'::uuid AND \w+ IS NOT DISTINCT FROM /,
      `UPDATE missing an IS NOT DISTINCT FROM guard:\n${block}`,
    );
  }
});

test('the migration is wrapped in BEGIN/COMMIT', () => {
  assert.match(sql, /^BEGIN;/m);
  assert.match(sql, /^COMMIT;/m);
});

test('every addition category from the source JSON appears in the migration', () => {
  // Pinned literally (not re-read from the review scratchpad, which is
  // ephemeral) so a category typo in a future regeneration is caught even if
  // the JSON that produced it is gone. Note "Furniture" (not "Furniture &
  // Home") — renamed during review to avoid colliding with the live "Home &
  // Rooms" category; this is the exact string in words-a1.2-additions.json.
  const categories = [
    'Travel & Transport',
    'Places in Town',
    'Health & Doctor',
    'Furniture',
    'Free Time & Hobbies',
    'Money & Shopping',
    'Numbers 100-1000 & Ordinals',
    'Weather',
  ];
  for (const cat of categories) {
    assert.ok(sql.includes(`'${cat}'`), `Migration is missing category "${cat}"`);
  }
});

test('VOCAB_WORD_COUNT is the live 2049 plus this migration\'s 166 additions', () => {
  assert.equal(VOCAB_WORD_COUNT, 2049 + 166);
});
